// Hero classes the player can pick (double-click the character). Each gives two passives (CLASS_PASSIVES below) and has its own
// pixel portrait (hero_<id> full figure) generated by scripts/pixel.
import type { PixelIconName } from './pixelIcons';

export type PlayerClassId = 'warrior' | 'paladin' | 'ranger' | 'mage';

export interface PlayerClassInfo {
	id: PlayerClassId;
	label: string;
	race: string;
	blurb: string;
	/** Accent for the picker card and its glow */
	accent: string;
	full: PixelIconName;
}

export const DEFAULT_PLAYER_CLASS: PlayerClassId = 'warrior';

